const s = $input.first().json || {};

function fail(detail) {
  return [{ json: { ...s, _2e_fail: { code: 'INTERNAL_CONTRACT_ERROR', detail } } }];
}

if (s._2e_fail) return [{ json: s }];
if (!Array.isArray(s._2e_hydration_plan)) return fail('_2e_hydration_plan missing at live hydration provider entry');

const endpoint = s._2e_endpoints && s._2e_endpoints.HYDRATION;
if (typeof endpoint !== 'string' || !endpoint.trim()) return fail('_2e_endpoints.HYDRATION missing at live hydration provider entry');

const configured = s.l2e_config && s.l2e_config.hydration_endpoint_identity;
if (typeof configured === 'string' && configured.trim() && configured.trim() !== endpoint.trim()) {
  return fail('HYDRATION endpoint identity changed after Layer 2E entry');
}

const APOLLO_ENDPOINT = 'https://api.apollo.io/api/v1/people/match';
if (endpoint.trim() !== APOLLO_ENDPOINT) {
  return fail('live Apollo hydration requires hydration_endpoint_identity=' + APOLLO_ENDPOINT);
}

const maxPool = s._2e && s._2e.MAX_VERIFICATION_POOL;
if (!Number.isInteger(maxPool) || maxPool <= 0) return fail('_2e.MAX_VERIFICATION_POOL missing or invalid');

const queue = s._2e_hydration_plan
  .filter(p => p && p.required === true)
  .slice()
  .sort((a,b) => a.discovery_rank - b.discovery_rank);

if (queue.length > maxPool) return fail('hydration call count exceeds MAX_VERIFICATION_POOL');

const seenRanks = new Set();
const seenKeys = new Set();
for (const p of queue) {
  if (!Number.isInteger(p.discovery_rank) || p.discovery_rank < 1) return fail('invalid hydration discovery_rank');
  if (seenRanks.has(p.discovery_rank)) return fail('duplicate hydration discovery_rank: ' + p.discovery_rank);
  seenRanks.add(p.discovery_rank);

  if (typeof p.stable_candidate_key !== 'string' || !p.stable_candidate_key.trim()) return fail('hydration candidate missing stable_candidate_key');
  if (seenKeys.has(p.stable_candidate_key)) return fail('duplicate hydration stable_candidate_key: ' + p.stable_candidate_key);
  seenKeys.add(p.stable_candidate_key);

  const a = p.anchor || {};
  const r = p.request || {};
  if (a.provider_namespace !== 'apollo' || typeof a.person_id !== 'string' || !a.person_id.trim()) {
    return fail('invalid Apollo hydration anchor for ' + p.stable_candidate_key);
  }
  if (r.provider_namespace !== a.provider_namespace || r.person_id !== a.person_id) {
    return fail('pre-call hydration identity binding mismatch for ' + p.stable_candidate_key);
  }
}

const clean = { ...s };
delete clean._2e_hydration_fixture;

return [{
  json: {
    ...clean,
    _hyd_live: {
      endpoint_identity: endpoint.trim(),
      queue,
      cursor: 0,
      logical_call_count: 0,
      results: [],
      events: [],
      service_state: {
        state: 'AVAILABLE',
        breaker_key: endpoint.trim(),
        last_logical_call_index: null,
        consecutive_transient_exhaustions: 0
      },
      current: null,
      attempt_result: null,
      retry_delay_ms: null
    }
  }
}];

const s = $input.first().json || {};
if (s._2e_fail) return [{ json: s }];
const live = s._hyd_live;
if (!live || !Array.isArray(live.queue)) return [{ json: { ...s, _2e_fail: { code:'INTERNAL_CONTRACT_ERROR', detail:'missing _hyd_live queue' } } }];
if (live.service_state.state !== 'AVAILABLE') return [{ json: s }];
if (live.cursor >= live.queue.length) return [{ json: s }];

const p = live.queue[live.cursor];
const lci = live.logical_call_count + 1;
return [{
  json: {
    ...s,
    _hyd_live: {
      ...live,
      logical_call_count: lci,
      current: {
        stable_candidate_key: p.stable_candidate_key,
        discovery_rank: p.discovery_rank,
        anchor: p.anchor,
        request: p.request,
        logical_call_index: lci,
        attempt: 1
      },
      attempt_result: null,
      retry_delay_ms: null
    }
  }
}];

const s = $input.first().json || {};
if (s._2e_fail) return [{ json: s }];
const c = s._hyd_live && s._hyd_live.current;
if (!c || !c.request || c.request.provider_namespace !== 'apollo' || typeof c.request.person_id !== 'string' || !c.request.person_id) {
  return [{ json: { ...s, _2e_fail: { code:'INTERNAL_CONTRACT_ERROR', detail:'invalid current hydration request before HTTP call' } } }];
}
if (c.request.person_id !== (c.anchor && c.anchor.person_id)) {
  return [{ json: { ...s, _2e_fail: { code:'INTERNAL_CONTRACT_ERROR', detail:'hydration requested Person ID differs from anchor immediately before call' } } }];
}
return [{ json: s }];

const incoming = $input.first().json || {};
let s;
try { s = $('2E Hydration - Prepare HTTP Attempt').item.json || {}; }
catch (e) { s = {}; }
if (s._2e_fail) return [{ json: s }];
const live = s._hyd_live || {};
const c = live.current || {};
const attempt = Number(c.attempt || 1);

function errText(x) {
  if (x === null || x === undefined) return '';
  if (typeof x === 'string') return x;
  try { return JSON.stringify(x); } catch (e) { return String(x); }
}
function statusCodeOf(o) {
  const vals = [o.statusCode, o.status_code, o.http_status, o.error && o.error.statusCode, o.error && o.error.status];
  for (const v of vals) {
    const n = Number(v);
    if (Number.isInteger(n) && n >= 100 && n <= 599) return n;
  }
  const m = errText(o.error || o.message || '').match(/\b([1-5]\d{2})\b/);
  return m ? Number(m[1]) : null;
}
function safeLinkedIn(u) {
  if (typeof u !== 'string') return null;
  let x = u.trim();
  if (!x) return null;
  if (!/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\//.test(x)) x = 'https://' + x;
  const m = x.match(/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\/([^\/?#]*)([^?#]*)/);
  if (!m) return null;
  let host = m[1].toLowerCase();
  if (host.includes('@')) return null;
  host = host.replace(/:\d+$/, '').replace(/^www\./, '');
  let path = (m[2] || '').toLowerCase();
  if (path.length > 1 && path.endsWith('/')) path = path.slice(0,-1);
  if (host !== 'linkedin.com' || !/^\/in\/[^\/]+$/.test(path)) return null;
  return host + path;
}

const http = statusCodeOf(incoming);
const nodeError = incoming.error ? errText(incoming.error).toLowerCase() : '';
let transient = false;
let retry = false;
let exhausted = false;
let fixture_status = null;
let failure_scope = null;
let normalized_error_class = null;
let returned_person_id = null;
let linkedin_url = null;
let outcome = null;
let error_code = null;

if (incoming.error && http === null) {
  transient = true;
  normalized_error_class = /timeout|timed out|etimedout/.test(nodeError) ? 'TIMEOUT' : 'NETWORK_ERROR';
  error_code = normalized_error_class;
} else if (http === 408 || http === 425 || http === 429 || (http !== null && http >= 500 && http <= 599)) {
  transient = true;
  normalized_error_class = 'HTTP_TRANSIENT_' + http;
  error_code = normalized_error_class;
} else if (http === 401 || http === 403) {
  fixture_status = 'PERMANENT_ERROR';
  failure_scope = 'SYSTEMIC';
  normalized_error_class = 'HTTP_' + http;
  error_code = normalized_error_class;
  outcome = { kind:'systemic', normalized_error_class };
} else if (http !== null && (http < 200 || http >= 300)) {
  fixture_status = 'PERMANENT_ERROR';
  failure_scope = 'CANDIDATE';
  normalized_error_class = 'HTTP_' + http;
  error_code = normalized_error_class;
  outcome = { kind:'permanent' };
} else {
  const body = incoming.body !== undefined ? incoming.body : incoming;
  let person = null;
  let explicitNull = false;
  if (body && Object.prototype.hasOwnProperty.call(body,'person')) {
    explicitNull = body.person === null;
    if (body.person && typeof body.person === 'object') person = body.person;
  } else if (body && body.data && Object.prototype.hasOwnProperty.call(body.data,'person')) {
    explicitNull = body.data.person === null;
    if (body.data.person && typeof body.data.person === 'object') person = body.data.person;
  } else if (body && typeof body === 'object' && !Array.isArray(body) && (body.id || body.linkedin_url)) {
    person = body;
  }

  if (explicitNull) {
    fixture_status = 'NOT_FOUND';
    outcome = { kind:'ok' };
  } else if (!person) {
    fixture_status = 'INVALID_RESPONSE';
    failure_scope = 'SYSTEMIC';
    normalized_error_class = 'INVALID_SHARED_ENVELOPE';
    error_code = normalized_error_class;
    outcome = { kind:'systemic', normalized_error_class };
  } else if (typeof person.id !== 'string' || !person.id.trim()) {
    fixture_status = 'INVALID_RESPONSE';
    failure_scope = 'CANDIDATE';
    normalized_error_class = 'MISSING_RETURNED_PERSON_ID';
    error_code = normalized_error_class;
    outcome = { kind:'permanent' };
  } else {
    fixture_status = 'MATCH';
    returned_person_id = person.id.trim();
    linkedin_url = safeLinkedIn(person.linkedin_url);
    outcome = { kind:'ok' };
  }
}

if (transient) {
  retry = attempt < 3;
  exhausted = attempt >= 3;
  outcome = null;
}

const retryDelay = retry ? (attempt === 1 ? 2000 : 5000) : null;

return [{
  json: {
    ...s,
    _hyd_live: {
      ...live,
      attempt_result: {
        retry,
        exhausted,
        fixture_status,
        failure_scope,
        normalized_error_class,
        returned_person_id,
        linkedin_url,
        outcome,
        http_status: http,
        error_code
      },
      retry_delay_ms: retryDelay
    }
  }
}];

const s = $input.first().json || {};
if (s._2e_fail) return [{ json:s }];
const live=s._hyd_live||{};
const c=live.current||{};
if (!live.attempt_result || live.attempt_result.retry !== true) {
  return [{ json:{...s,_2e_fail:{code:'INTERNAL_CONTRACT_ERROR',detail:'retry advance reached without retry=true'}} }];
}
const nextAttempt=Number(c.attempt||1)+1;
if (nextAttempt>3) return [{ json:{...s,_2e_fail:{code:'INTERNAL_CONTRACT_ERROR',detail:'hydration retry exceeded 3 attempts'}} }];
return [{json:{...s,_hyd_live:{...live,current:{...c,attempt:nextAttempt},attempt_result:null}}}];

const s = $input.first().json || {};
if (s._2e_fail) return [{ json:s }];
const live=s._hyd_live||{};
const c=live.current||{};
const ar=live.attempt_result||{};
if (!c.stable_candidate_key || !Number.isInteger(c.logical_call_index)) {
  return [{json:{...s,_2e_fail:{code:'INTERNAL_CONTRACT_ERROR',detail:'commit missing active hydration logical call'}}}];
}
if (ar.retry === true) return [{json:{...s,_2e_fail:{code:'INTERNAL_CONTRACT_ERROR',detail:'commit reached while hydration retry still required'}}}];

let state=live.service_state && live.service_state.state || 'AVAILABLE';
let streak=Number(live.service_state && live.service_state.consecutive_transient_exhaustions || 0);
let lastIdx=live.service_state && live.service_state.last_logical_call_index || null;
const events=Array.isArray(live.events)?live.events.slice():[];
const results=Array.isArray(live.results)?live.results.slice():[];
const endpoint=live.endpoint_identity;
const lci=c.logical_call_index;
const occurredAt=s._2e_now || new Date().toISOString();

if (ar.exhausted === true) {
  streak += 1;
  lastIdx = lci;
  if (streak >= 2) {
    events.push({
      operation:'HYDRATION',
      service_endpoint_identity:endpoint,
      previous_state:'AVAILABLE',
      new_state:'CIRCUIT_OPEN',
      trigger_stable_candidate_key:c.stable_candidate_key,
      logical_call_index:lci,
      normalized_error_class:'TRANSIENT_EXHAUSTED',
      attempts:Number(c.attempt||3),
      http_status:ar.http_status ?? null,
      error_code:ar.error_code ?? null,
      occurred_at:occurredAt
    });
    state='CIRCUIT_OPEN';
    streak=2;
  }
} else if (ar.outcome && ar.outcome.kind === 'systemic') {
  streak=0;
  lastIdx=lci;
  state='OPEN_FAILED';
  events.push({
    operation:'HYDRATION',
    service_endpoint_identity:endpoint,
    previous_state:'AVAILABLE',
    new_state:'OPEN_FAILED',
    trigger_stable_candidate_key:c.stable_candidate_key,
    logical_call_index:lci,
    normalized_error_class:ar.normalized_error_class || 'SYSTEMIC_FAILURE',
    attempts:Number(c.attempt||1),
    http_status:ar.http_status ?? null,
    error_code:ar.error_code ?? null,
    occurred_at:occurredAt
  });
} else {
  streak=0;
  lastIdx=lci;
}

results.push({
  stable_candidate_key:c.stable_candidate_key,
  discovery_rank:c.discovery_rank,
  called:true,
  anchor:c.anchor,
  request:c.request,
  logical_call_index:lci,
  attempt_count:Number(c.attempt||1),
  exhausted:ar.exhausted===true,
  outcome:ar.outcome||null,
  fixture_status:ar.fixture_status||null,
  failure_scope:ar.failure_scope||null,
  normalized_error_class:ar.normalized_error_class||null,
  returned_person_id:ar.returned_person_id||null,
  linkedin_url:ar.linkedin_url||null,
  http_status:ar.http_status ?? null,
  error_code:ar.error_code ?? null,
  service_state_after:state
});

let cursor=live.cursor+1;
if (state !== 'AVAILABLE') {
  while (cursor < live.queue.length) {
    const p=live.queue[cursor];
    results.push({
      stable_candidate_key:p.stable_candidate_key,
      discovery_rank:p.discovery_rank,
      called:false,
      anchor:p.anchor,
      request:p.request,
      logical_call_index:null,
      blocked_by_breaker_state:state
    });
    cursor += 1;
  }
}

return [{json:{
  ...s,
  _hyd_live:{
    ...live,
    cursor,
    results,
    events,
    current:null,
    attempt_result:null,
    retry_delay_ms:null,
    service_state:{
      state,
      breaker_key:endpoint,
      last_logical_call_index:lastIdx,
      consecutive_transient_exhaustions:state==='OPEN_FAILED'?0:(state==='CIRCUIT_OPEN'?2:streak)
    }
  }
}}];

const s = $input.first().json || {};
if (s._2e_fail) return [{ json:s }];
const live=s._hyd_live;
if (!live || !Array.isArray(live.results) || !live.service_state) {
  return [{json:{...s,_2e_fail:{code:'INTERNAL_CONTRACT_ERROR',detail:'live hydration state missing at finalize'}}}];
}
if (live.cursor !== live.queue.length) {
  return [{json:{...s,_2e_fail:{code:'INTERNAL_CONTRACT_ERROR',detail:'live hydration finalized before queue exhaustion'}}}];
}
const out={...s};
delete out._hyd_live;
delete out._2e_hydration_fixture;
out._2e_hydration_raw=live.results;
out._2e_hydration_service={...live.service_state};
out._2e_circuit_events=(Array.isArray(s._2e_circuit_events)?s._2e_circuit_events:[]).concat(live.events||[]);
return [{json:out}];
